       }

       .detail-card,
       .section-card,
       .product-card,
       .deal-card,
       .story-card,
       .spotlight-card {
         border: 1px solid var(--color-border);
         border-radius: var(--radius-md);
         background: linear-gradient(180deg, rgba(19, 35, 58, 0.95), rgba(11, 21, 37, 0.98));
       }

       .detail-card {
         padding: 1.25rem;
       }

       .detail-card strong,
       .detail-card h2,
       .detail-card h3 {
         display: block;
         margin-bottom: 0.4rem;
         font-size: 1.05rem;
       }

       .detail-card h2,
       .detail-card h3 {
         margin-top: 0;
         color: var(--color-text);
       }

       .detail-card p {
         margin: 0;
         color: var(--color-muted-text);
         line-height: 1.6;
       }

       .detail-card__meta {
         display: inline-flex;
         margin-top: 1rem;
         padding: 0.45rem 0.7rem;
         border-radius: 999px;
         background: rgba(147, 197, 253, 0.12);
         color: var(--color-link);
         font-size: 0.9rem;
         font-weight: 700;
       }

       .spotlight-grid {
         display: grid;
         grid-template-columns: repeat(3, minmax(0, 1fr));
         gap: 1rem;
         margin-top: 1.25rem;
       }

       .spotlight-card {
         padding: 1.25rem;
       }

       .spotlight-card__value {
         display: block;
         margin-bottom: 0.45rem;
         color: var(--color-accent);
         font-size: 1.45rem;
         font-weight: 800;
       }

       .spotlight-card p {
         margin: 0;
         color: var(--color-muted-text);
         line-height: 1.55;
       }

       .section {
         padding: 0 0 3rem;
       }

       .section-card {
         padding: clamp(1.25rem, 2vw, 1.75rem);
       }

       .section__intro {
         display: flex;
         flex-wrap: wrap;
         gap: 1rem;
         align-items: end;
         justify-content: space-between;
         margin-bottom: 1.5rem;
       }

       .section__intro h2 {
         margin: 0.2rem 0 0;
         font-size: clamp(1.8rem, 4vw, 2.6rem);
         line-height: 1.1;
       }

       .section__intro p {
         max-width: 40rem;
         margin: 0;
         color: var(--color-muted-text);
         line-height: 1.7;
       }

       .section__link {
         color: var(--color-link);
         font-weight: 700;
       }

       .product-grid,
       .deal-grid,
       .story-grid {
         display: grid;
         gap: 1rem;
       }

       .product-grid {
         grid-template-columns: repeat(4, minmax(0, 1fr));
       }

       .deal-grid {
         grid-template-columns: repeat(3, minmax(0, 1fr));
       }

       .story-grid {
         grid-template-columns: repeat(3, minmax(0, 1fr));
       }

       .product-card,
       .deal-card,
       .story-card {
         overflow: hidden;
       }

       .product-card__art,
       .story-card__art {
         position: relative;
         min-height: 12rem;
         border-bottom: 1px solid rgba(147, 197, 253, 0.12);
         background:
           radial-gradient(circle at top right, rgba(147, 197, 253, 0.24), transparent 34%),
           linear-gradient(135deg, rgba(56, 189, 248, 0.1), rgba(192, 132, 252, 0.2)),
           linear-gradient(180deg, #13233a 0%, #0b1525 100%);
       }

       .product-card__art::before,
       .story-card__art::before {
         content: "";
         position: absolute;
         inset: 1.4rem;
         border-radius: 24px;
         border: 1px solid rgba(255, 255, 255, 0.08);
       }

       .product-card__art::after,
       .story-card__art::after {
         content: "";
         position: absolute;
         inset: auto 1.4rem 1.4rem auto;
         width: 4.75rem;
         height: 4.75rem;
         border-radius: 50%;
         background: radial-gradient(circle, rgba(192, 132, 252, 0.34), transparent 68%);
       }

       .product-card__body,
       .deal-card__body,
       .story-card__body {
         padding: 1.25rem;
       }

       .product-card__kicker,
       .deal-card__kicker,
       .story-card__kicker {
         display: inline-flex;
         margin-bottom: 0.7rem;
         padding: 0.38rem 0.7rem;
         border-radius: 999px;
         background: rgba(147, 197, 253, 0.12);
         color: var(--color-link);
         font-size: 0.82rem;
         font-weight: 800;
         letter-spacing: 0.06em;
         text-transform: uppercase;
       }

       .product-card h3,
       .deal-card h3,
       .story-card h3 {
         margin: 0;
         font-size: 1.2rem;
         line-height: 1.3;
       }

       .product-card p,
       .deal-card p,
       .story-card p {
         margin: 0.7rem 0 0;
         color: var(--color-muted-text);
         line-height: 1.65;
       }

       .price-row {
         display: flex;
         flex-wrap: wrap;
         gap: 0.6rem 1rem;
         align-items: baseline;
         margin-top: 1rem;
       }

       .price-row__current {
         font-size: 1.2rem;
         font-weight: 800;
       }

       .price-row__compare {
         color: var(--color-muted-text);
         text-decoration: line-through;
       }

       .card-link {
         display: inline-flex;
         margin-top: 1rem;
         color: var(--color-link);
         font-weight: 700;
       }

       .deal-card {
         position: relative;
       }

       .deal-card__badge {
         position: absolute;
         top: 1rem;
         right: 1rem;
         padding: 0.45rem 0.7rem;
         border-radius: 999px;
         background: rgba(134, 239, 172, 0.12);
         color: var(--color-success);
         font-size: 0.86rem;
         font-weight: 800;
       }

       .deal-card__meta {
         display: grid;
         gap: 0.65rem;
         margin-top: 1rem;
         padding-top: 1rem;
         border-top: 1px solid rgba(255, 255, 255, 0.06);
       }

       .deal-card__meta div {
         display: flex;
         justify-content: space-between;
         gap: 1rem;
         color: var(--color-muted-text);
       }

       .deal-card__meta strong {
         color: var(--color-text);
       }

       .story-card__art {
         min-height: 10rem;
         background:
           radial-gradient(circle at bottom left, rgba(125, 211, 252, 0.2), transparent 34%),
           linear-gradient(135deg, rgba(192, 132, 252, 0.14), rgba(56, 189, 248, 0.1)),
           linear-gradient(180deg, #0f1b2d 0%, #0b1525 100%);
       }

       .site-footer {
         display: grid;
         grid-template-columns: minmax(0, 1.2fr) minmax(0, 0.8fr);
         gap: 1rem;
         padding: 0 0 2rem;
       }

       .footer-card {
         padding: 1.4rem;
         border: 1px solid var(--color-border);
         border-radius: var(--radius-md);
         background: linear-gradient(180deg, rgba(15, 27, 45, 0.95), rgba(10, 18, 31, 0.98));
       }

       .footer-card p,
       .footer-card ul {
         margin: 0.75rem 0 0;
         color: var(--color-muted-text);
         line-height: 1.7;
       }

       .footer-links {
         display: flex;
         flex-wrap: wrap;
         gap: 0.75rem 1.25rem;
         padding: 0;
         list-style: none;
       }

       .footer-links a {
         color: var(--color-link);
       }

       .sr-only {
         position: absolute;
         width: 1px;
         height: 1px;
         padding: 0;
         margin: -1px;
         overflow: hidden;
         clip: rect(0, 0, 0, 0);
         white-space: nowrap;
         border: 0;
       }

       @media (max-width: 1040px) {
         .hero__panel,
         .site-footer {
           grid-template-columns: 1fr;
         }

         .product-grid {
           grid-template-columns: repeat(2, minmax(0, 1fr));
         }

         .deal-grid,
         .story-grid,
         .spotlight-grid {
           grid-template-columns: 1fr;
         }
       }

       @media (max-width: 700px) {
         .announcement__content,
         .site-header,
         .section__intro {
           align-items: start;
         }

         .product-grid {
           grid-template-columns: 1fr;
         }

         .hero h1 {
           max-width: none;
         }
       }

       @media (prefers-reduced-motion: reduce) {
         html {
           scroll-behavior: auto;
         }

         *,
         *::before,
         *::after {
           animation-duration: 0.01ms !important;
           animation-iteration-count: 1 !important;
           transition-duration: 0.01ms !important;
         }
       }

       @media (forced-colors: active) {
         .skip-link,
         .button-link,
         .detail-card,
         .section-card,
         .product-card,
         .deal-card,
         .story-card,
         .spotlight-card,
         .footer-card,
         .brand__mark,
         .site-nav a {
           border: 1px solid ButtonBorder;
         }

         .skip-link,
         .button-link--primary,
         .button-link--secondary {
           background: ButtonFace;
           color: ButtonText;
         }

         .product-card__kicker,
         .deal-card__kicker,
         .story-card__kicker,
         .detail-card__meta,
         .deal-card__badge {
           border: 1px solid ButtonBorder;
         }

         :focus-visible {
           outline-color: Highlight;
         }
       }
     </style>
   </head>
   <body>
     <a class="skip-link" href="#main-content">Skip to main content</a>
     <div id="app" class="page-shell"></div>
     <script>
       const featuredProducts = [
         {
           label: "New arrival",
           name: "Aura Bomber Jacket",
           description:
             "A soft-structure layer with matte hardware, insulating quilting, and an easy city silhouette.",
           price: "$248",
           compareAt: "$320",
           href: "#featured-products"
         },
         {
           label: "Best seller",
           name: "Sable Knit Set",
           description:
             "A matching ribbed top and wide-leg pant designed for long flights, late dinners, and every hour between.",
           price: "$184",
           compareAt: "$240",
           href: "#featured-products"
         },
         {
           label: "Editors' pick",
           name: "Halo Leather Tote",
           description:
             "Structured enough for weekdays, relaxed enough for weekends, finished with contrast-lined storage pockets.",
           price: "$196",
           compareAt: "$260",
           href: "#featured-products"
         },
         {
           label: "Limited run",
           name: "Lumen Runner",
           description:
             "Lightweight traction, responsive cushioning, and tonal panels that move easily from commute to studio.",
           price: "$158",
           compareAt: "$210",
           href: "#featured-products"
         }
       ];

       const deals = [
         {
           label: "Weekend drop",
           title: "Up to 40% off travel layers",
           description:
             "Packable coats, smart knits, and weather-ready accessories built for overnight bags and red-eye returns.",
           badge: "Save 40%",
           ends: "Ends Sunday at midnight",
           code: "MIDNIGHT40",
           href: "#deals"
         },
         {
           label: "Member reward",
           title: "Two accessories, one elevated gift",
           description:
             "Choose any two finishing pieces and receive complimentary wrap plus a premium leather card case.",
           badge: "Gift included",
           ends: "While sets last",
           code: "GIFTSET",
           href: "#deals"
         },
         {
           label: "Studio edit",
           title: "15% off monochrome performance",
           description:
             "High-stretch essentials with reflective trims and sculpted seams, curated for low-light miles.",
           badge: "Extra 15%",
           ends: "Members all week",
           code: "NIGHTMOVE",
           href: "#deals"
         }
       ];

       const stories = [
         {
           label: "Editorial",
           title: "How to build a wardrobe that works after dark",
           description:
             "Three modular formulas from the styling team for sharper layering, richer texture, and easier night-out dressing.",
           href: "#journal"
         },
         {
           label: "Behind the brand",
           title: "Inside the materials library for our fall capsule",
           description:
             "A look at the recycled nylons, brushed wool blends, and low-shine finishes that define the season.",
           href: "#journal"
         },
         {
           label: "City guide",
           title: "48 hours of food, music, and retail in Copenhagen",
           description:
             "The places our creative team bookmarked for quiet mornings, standout design stores, and late reservations.",
           href: "#journal"
         }
       ];

       const spotlightItems = [
         {
           value: "Free express shipping",
           text: "For orders over $150 across apparel, accessories, and home."
         },
         {
           value: "Curated capsule drops",
           text: "Limited weekly edits designed around a single mood and color story."
         },
         {
           value: "Editorial-led merchandising",
           text: "Shop the same looks featured in the journal and weekly creative notes."
         }
       ];

       const IconMark = () => `
         <svg viewBox="0 0 24 24" aria-hidden="true" focusable="false">
           <path d="M12 2 4 7v10l8 5 8-5V7l-8-5Zm0 2.3 5.7 3.4L12 11.1 6.3 7.7 12 4.3Zm-6 5.1 5 3v6.5l-5-3V9.4Zm7 9.5v-6.5l5-3v6.5l-5 3Z"></path>
         </svg>
       `;

       const SectionIntro = ({ eyebrow, title, titleId, copy, linkLabel, linkHref }) => `
         <div class="section__intro">
           <div>
             <p class="eyebrow"><span class="eyebrow__dot" aria-hidden="true"></span>${eyebrow}</p>
             <h2 id="${titleId}">${title}</h2>
             <p>${copy}</p>
           </div>
           <a class="section__link" href="${linkHref}">${linkLabel}</a>
         </div>
       `;

       const ProductCard = (product) => `
         <article class="product-card">
           <div class="product-card__art" aria-hidden="true"></div>
           <div class="product-card__body">
             <span class="product-card__kicker">${product.label}</span>
             <h3>${product.name}</h3>
             <p>${product.description}</p>
             <div class="price-row" aria-label="Pricing">
               <span class="price-row__current">${product.price}</span>
               <span class="price-row__compare">${product.compareAt}</span>
             </div>
             <a class="card-link" href="${product.href}">View ${product.name}</a>
           </div>
         </article>
       `;

       const DealCard = (deal) => `
         <article class="deal-card">
           <span class="deal-card__badge">${deal.badge}</span>
           <div class="deal-card__body">
             <span class="deal-card__kicker">${deal.label}</span>
             <h3>${deal.title}</h3>
             <p>${deal.description}</p>
             <div class="deal-card__meta">
               <div><span>Offer window</span><strong>${deal.ends}</strong></div>
               <div><span>Promo code</span><strong>${deal.code}</strong></div>
             </div>
             <a class="card-link" href="${deal.href}">Shop ${deal.title}</a>
           </div>
         </article>
       `;

       const StoryCard = (story) => `
         <article class="story-card">
           <div class="story-card__art" aria-hidden="true"></div>
           <div class="story-card__body">
             <span class="story-card__kicker">${story.label}</span>
             <h3>${story.title}</h3>
             <p>${story.description}</p>
             <a class="card-link" href="${story.href}">Read ${story.title}</a>
           </div>
         </article>
       `;

       const Header = () => `
         <header>
           <div class="announcement">
             <div class="announcement__content">
               <span><strong>Tonight only:</strong> complimentary express delivery on curated orders over $150.</span>
               <span>New capsule launches every Thursday at 8 PM ET.</span>
             </div>
           </div>
           <div class="site-header">
             <a class="brand" href="#top" aria-label="Nocturne Supply home">
               <span class="brand__mark">${IconMark()}</span>
               <span>
                 <span class="brand__name">Nocturne Supply</span>
                 <span class="brand__tagline">Refined essentials for evening retail</span>
               </span>
             </a>
             <nav class="site-nav" aria-label="Primary">
               <ul>
                 <li><a href="#featured-products">Featured</a></li>
                 <li><a href="#deals">Deals</a></li>
                 <li><a href="#journal">Journal</a></li>
                 <li><a href="#service">Service</a></li>
               </ul>
             </nav>
           </div>
         </header>
       `;

       const Hero = () => `
         <section class="hero" aria-labelledby="hero-title">
           <div class="hero__panel">
             <div>
               <p class="eyebrow"><span class="eyebrow__dot" aria-hidden="true"></span>New season retail edit</p>
               <h1 id="hero-title">Style the season with quiet drama.</h1>
               <p class="hero__copy">
                 Discover elevated layers, giftable accessories, and editorial picks arranged like a modern storefront:
                 high contrast, tactile texture, and versatile pieces that feel polished from first light to final plans.
               </p>
               <div class="hero__actions">
                 <a class="button-link button-link--primary" href="#featured-products">Shop featured products</a>
                 <a class="button-link button-link--secondary" href="#journal">Explore the editorial</a>
               </div>
               <div class="spotlight-grid" aria-label="Shopping highlights">
                 ${spotlightItems
                   .map(
                     (item) => `
                       <div class="spotlight-card">
                         <span class="spotlight-card__value">${item.value}</span>
                         <p>${item.text}</p>
                       </div>
                     `
                   )
                   .join("")}
               </div>
             </div>
             <section class="hero__details" aria-labelledby="hero-note-title">
               <div class="detail-card">
                 <h2 id="hero-note-title">This week's store note</h2>
                 <p>
                   The latest home page pairs product discovery with magazine-style pacing so shoppers can move from
                   intent to inspiration without losing the thread.
                 </p>
                 <span class="detail-card__meta">Updated for the weekend launch</span>
               </div>
               <div class="detail-card">
                 <h3>Popular right now</h3>
                 <p>
                   Compact travel silhouettes, tonal sneakers, and soft tailoring are leading every category this week.
                 </p>
                 <span class="detail-card__meta">Most saved in the last 24 hours</span>
               </div>
             </section>
           </div>
         </section>
       `;

       const FeaturedSection = () => `
         <section class="section" id="featured-products" aria-labelledby="featured-title">
           <div class="section-card">
             ${SectionIntro({
               eyebrow: "Featured products",
               title: "Best-in-class pieces, chosen like an in-store front table",
               titleId: "featured-title",
               copy:
                 "These four arrivals anchor the current collection with premium fabrication, polished utility, and styling flexibility for every hour of the day.",
               linkLabel: "Browse all featured arrivals",
               linkHref: "#featured-products"
             })}
             <div class="product-grid">
               ${featuredProducts.map(ProductCard).join("")}
             </div>
           </div>
         </section>
       `;

       const DealsSection = () => `
         <section class="section" id="deals" aria-labelledby="deals-title">
           <div class="section-card">
             ${SectionIntro({
               eyebrow: "Deals",
               title: "Offers that feel curated, not crowded",
               titleId: "deals-title",
               copy:
                 "Each promotion is built around a complete mood so shoppers can unlock value without wading through a noisy sale wall.",
               linkLabel: "See every active offer",
               linkHref: "#deals"
             })}
             <div class="deal-grid">
               ${deals.map(DealCard).join("")}
             </div>
           </div>
         </section>
       `;

       const JournalSection = () => `
         <section class="section" id="journal" aria-labelledby="journal-title">
           <div class="section-card">
             ${SectionIntro({
               eyebrow: "Editorial content",
               title: "A journal that merchandises through stories",
               titleId: "journal-title",
               copy:
                 "The editorial mix keeps the home page feeling alive, connecting trend cues, material thinking, and city culture back to the products on the floor.",
               linkLabel: "Open the full journal",
               linkHref: "#journal"
             })}
             <div class="story-grid">
               ${stories.map(StoryCard).join("")}
             </div>
           </div>
         </section>
       `;

       const Footer = () => `
         <footer class="site-footer" id="service">
           <section class="footer-card" aria-labelledby="service-title">
             <p class="eyebrow"><span class="eyebrow__dot" aria-hidden="true"></span>Service</p>
             <h2 id="service-title">Premium retail support, built into the experience</h2>
             <p>
               Concierge styling, easy returns, and clear delivery windows help the storefront feel as considered as the
               collection itself.
             </p>
           </section>
           <section class="footer-card" aria-labelledby="footer-links-title">
             <h2 id="footer-links-title" class="sr-only">Helpful links</h2>
             <ul class="footer-links">
               <li><a href="#featured-products">Shop arrivals</a></li>
               <li><a href="#deals">Current offers</a></li>
               <li><a href="#journal">Editorial stories</a></li>
               <li><a href="#top">Back to top</a></li>
             </ul>
           </section>
         </footer>
       `;

       const App = () => `
         <div id="top">
           ${Header()}
           <main id="main-content" tabindex="-1">
             ${Hero()}
             ${FeaturedSection()}
             ${DealsSection()}
             ${JournalSection()}
           </main>
           ${Footer()}
         </div>
       `;

       document.getElementById("app").innerHTML = App();
     </script>
   </body>
 </html>

')
